import os, hashlib, filecmp
from pathlib import Path

src = Path(r'C:/Users/win/Desktop/alpha/_merge_incoming/alpha-main-generation-fixed-v2')
dst = Path(r'C:/Users/win/Desktop/alpha')

SKIP_NAMES = {'.git', '_merge_incoming', '__pycache__', '.venv', 'venv', 'node_modules', '.codegraph'}
SECRET_GLOBS = {'.env', '.wq_auth_state.json', 'cookies.json', 'alpha_state.json'}

def should_skip(rel: Path):
    parts = set(rel.parts)
    if parts & SKIP_NAMES: return True
    if any(p.startswith('.') and p.endswith('_cache') for p in rel.parts): return False
    name = rel.name
    if name in SECRET_GLOBS: return True
    if name.endswith('.sqlite') or name.endswith('.sqlite3'): return True
    if 'cookie' in name.lower() and name.endswith(('.json','.txt')): return True
    return False

def file_sha(p):
    h=hashlib.sha256()
    with open(p,'rb') as f:
        for chunk in iter(lambda: f.read(1<<20), b''):
            h.update(chunk)
    return h.hexdigest()

src_files = {}
for root, dirs, files in os.walk(src):
    dirs[:] = [d for d in dirs if d not in SKIP_NAMES and d != '__pycache__']
    for fn in files:
        p = Path(root)/fn
        rel = p.relative_to(src)
        if should_skip(rel): continue
        src_files[str(rel).replace('\\','/')] = p

dst_files = {}
for root, dirs, files in os.walk(dst):
    dirs[:] = [d for d in dirs if d not in SKIP_NAMES and d != '__pycache__' and d != '_merge_incoming']
    for fn in files:
        p = Path(root)/fn
        rel = p.relative_to(dst)
        if should_skip(rel): continue
        # skip local agent transcripts / terminals style
        if str(rel).replace('\\','/').startswith('.cursor/projects'): continue
        dst_files[str(rel).replace('\\','/')] = p

only_src = sorted(set(src_files)-set(dst_files))
only_dst = sorted(set(dst_files)-set(src_files))
changed = []
same = 0
for k in sorted(set(src_files)&set(dst_files)):
    if file_sha(src_files[k]) != file_sha(dst_files[k]):
        changed.append(k)
    else:
        same += 1

print('SRC', len(src_files), 'DST_TRACKABLE', len(dst_files))
print('SAME', same, 'CHANGED', len(changed), 'ONLY_SRC', len(only_src), 'ONLY_DST', len(only_dst))
